package handlers

import (
	"encoding/json"
	"net/http"
	"os"
	"path/filepath"
	"strings"
)

// sensitivePatterns mirrors the opencode.json permission.read deny list.
// These are never readable through the managed read — no proposal is ever
// emitted for them, inside or outside the project.
var sensitivePatterns = []string{
	"*.env", "*.env.*", "*.pem", "*.key",
	"envs/**", "**/envs/**",
}

// isSensitive reports whether target matches any sensitive pattern.
func isSensitive(target string) bool {
	base := filepath.Base(target)
	for _, p := range sensitivePatterns {
		if ok, _ := filepath.Match(p, base); ok {
			return true
		}
		if strings.Contains(p, "/") {
			if ok, _ := filepath.Match(p, target); ok {
				return true
			}
		}
	}
	return false
}

// isWithin reports whether target is inside directory (or equals it).
func isWithin(directory, target string) bool {
	d := filepath.Clean(directory)
	t := filepath.Clean(target)
	return t == d || strings.HasPrefix(t, d+string(filepath.Separator))
}

// coveredBy reports whether target is inside dir (or equals it).
func coveredBy(target, dir string) bool {
	d := filepath.Clean(dir)
	t := filepath.Clean(target)
	return t == d || strings.HasPrefix(t, d+string(filepath.Separator))
}

// readAllowed decides the gate tier for a target:
//   - sensitive            -> denied (no proposal)
//   - within directory     -> allowed
//   - covered by approved  -> allowed
//   - otherwise            -> needsApproval (proposal path = target's dir)
func readAllowed(directory, target string, approved []string) (ok bool, needsApproval bool, approvePath string) {
	if isSensitive(target) {
		return false, false, ""
	}
	if isWithin(directory, target) {
		return true, false, ""
	}
	for _, d := range approved {
		if coveredBy(target, d) {
			return true, false, ""
		}
	}
	return false, true, filepath.Dir(target)
}

// FolderStore supplies the approved-folder list used for read gating.
type FolderStore interface {
	ApprovedFolders() []string
}

// readHandler is the /v1/read endpoint: resolve -> gate -> read.
func readHandler(directory string, store FolderStore) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		var req struct {
			Path   string `json:"path"`
			Offset int    `json:"offset"`
			Limit  int    `json:"limit"`
		}
		if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
			http.Error(w, `{"error":"bad request"}`, http.StatusBadRequest)
			return
		}
		target := req.Path
		if target == "" {
			http.Error(w, `{"error":"path required"}`, http.StatusBadRequest)
			return
		}
		approved := store.ApprovedFolders()
		ok, needsApproval, approvePath := readAllowed(directory, target, approved)
		if !ok {
			if needsApproval {
				w.Header().Set("Content-Type", "application/json")
				w.WriteHeader(http.StatusForbidden)
				json.NewEncoder(w).Encode(map[string]any{
					"error":         "read denied: outside project and not covered by an approved folder",
					"needsApproval": true,
					"path":          approvePath,
				})
				return
			}
			http.Error(w, `{"error":"read denied: sensitive file"}`, http.StatusForbidden)
			return
		}

		info, err := os.Stat(target)
		if err != nil {
			http.Error(w, `{"error":"`+err.Error()+`"}`, http.StatusNotFound)
			return
		}
		if info.IsDir() {
			entries, err := os.ReadDir(target)
			if err != nil {
				http.Error(w, `{"error":"`+err.Error()+`"}`, http.StatusInternalServerError)
				return
			}
			names := make([]string, 0, len(entries))
			for _, e := range entries {
				names = append(names, e.Name())
			}
			w.Header().Set("Content-Type", "application/json")
			json.NewEncoder(w).Encode(map[string]any{"content": names})
			return
		}

		data, err := os.ReadFile(target)
		if err != nil {
			http.Error(w, `{"error":"`+err.Error()+`"}`, http.StatusInternalServerError)
			return
		}
		lines := strings.Split(string(data), "\n")
		start := req.Offset
		if start < 1 {
			start = 1
		}
		end := len(lines)
		if req.Limit > 0 && start+req.Limit-1 < end {
			end = start + req.Limit - 1
		}
		if start > end {
			start = end
		}
		content := strings.Join(lines[start-1:end], "\n")
		w.Header().Set("Content-Type", "application/json")
		json.NewEncoder(w).Encode(map[string]any{"content": content})
	}
}

// mountRead wires the /v1/read endpoint into the router.
func mountRead(r *chi.Mux, directory string, store FolderStore) {
	r.Post("/v1/read", readHandler(directory, store))
}

import { appendProposal } from "../proposals"

interface ReadArgs {
  filePath: string
  offset?: number
  limit?: number
}

interface ToolContext {
  sessionID?: string
  directory?: string
}

function dirname(p: string): string {
  const i = p.lastIndexOf("/")
  return i > 0 ? p.slice(0, i) : "/"
}

// findPendingApproval returns true if a pending folder-approve row for this
// path already exists in the session journal (dedup — one proposal per path).
async function findPendingApproval(
  directory: string,
  sessionID: string,
  path: string,
): Promise<boolean> {
  try {
    const fs = await import("node:fs")
    const file = `${directory}/.ai-proposals/${sessionID}.jsonl`
    if (!fs.existsSync(file)) return false
    const rows = fs.readFileSync(file, "utf8").split("\n")
    for (const row of rows) {
      if (!row.trim()) continue
      try {
        const p = JSON.parse(row)
        if (
          p.operation === "folder-approve" &&
          p.path === path &&
          p.status === "pending"
        ) {
          return true
        }
      } catch {
        /* skip malformed rows */
      }
    }
  } catch {
    /* journal unreadable — allow re-emit */
  }
  return false
}

export const readTool = (directory: string) => ({
  name: "read",
  description:
    "Read a file or directory, gated by the manage daemon. Project-internal reads are allowed except sensitive files (*.env, *.env.*, *.pem, *.key, envs/**). External reads emit a folder-approval proposal for the user to accept or reject in the review console (<leader>ar), then retry.",
  parameters: {
    type: "object",
    properties: {
      filePath: {
        type: "string",
        description: "Absolute path to the file or directory to read.",
      },
      offset: {
        type: "number",
        description: "1-indexed line to start reading from (default 1).",
      },
      limit: {
        type: "number",
        description: "Maximum number of lines to read (default: all).",
      },
    },
    required: ["filePath"],
  },
  async execute(args: ReadArgs, context: ToolContext) {
    const port = process.env.MANAGE_DAEMON_PORT ?? "4096"
    const res = await fetch(`http://localhost:${port}/v1/read`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        path: args.filePath,
        offset: args.offset ?? 0,
        limit: args.limit ?? 0,
      }),
    })
    if (res.ok) {
      const data = await res.json()
      return data.content
    }
    let body: any = {}
    try {
      body = await res.json()
    } catch {
      /* non-JSON error body */
    }
    if (res.status === 403 && body.needsApproval) {
      const sessionID = context?.sessionID ?? ""
      const approvePath: string = body.path ?? dirname(args.filePath)
      const existing = await findPendingApproval(directory, sessionID, approvePath)
      if (!existing) {
        await appendProposal(directory, sessionID, {
          operation: "folder-approve",
          path: approvePath,
          content: approvePath,
          reason: `read of ${args.filePath} requires folder approval`,
          group: "read-folder-approval",
          ts: Date.now(),
          status: "pending",
        })
      }
      return `read denied: ${args.filePath} is outside the project and not covered by an approved folder. A folder-approval proposal for ${approvePath} has been emitted — accept or reject it in the review console (<leader>ar), then retry the read.`
    }
    throw new Error(body.error ?? `read failed (${res.status})`)
  },
})

