      try {
        const p = JSON.parse(row)
        if (
          p.operation === "folder-approve" &&
          p.path === path &&
          p.status === "pending"
        ) {
          return true
        }
      } catch {
        /* skip malformed rows */
      }
    }
  } catch {
    /* journal unreadable — allow re-emit */
  }
  return false
}

